#!/bin/zsh
# Simulation study, fitting only (networks already generated by sim_generate.do).
# Usage (from the project root): enrichment/analysis/sim/run_fits.sh [NSIM] [LANES per scenario]
# Each lane fits a block of replications of one scenario and writes its own results file
# (joint_s<k>_l<lane>.csv); R fits run in one process per scenario. Logs: enrichment/analysis/sim/logs/
set -u
NSIM=${1:-100}
LANES=${2:-4}
STATA=/Applications/StataNow/StataMP.app/Contents/MacOS/StataMP
ROOT=$PWD
SIM=enrichment/analysis/sim
mkdir -p $SIM/logs $SIM/results
per=$(( (NSIM + LANES - 1) / LANES ))
for s in 1 2 3 4; do
  for l in $(seq 1 $LANES); do
    first=$(( (l - 1) * per + 1 )); last=$(( l * per )); (( last > NSIM )) && last=$NSIM
    (( first > NSIM )) && continue
    (
      mkdir -p $SIM/logs/s${s}_l$l && cd $SIM/logs/s${s}_l$l
      SCEN=$s OUTTAG=_l$l REPS="$(seq -s ' ' $first $last)" $STATA -e do ../../sim_fit_joint.do
    ) &
  done
  [[ -n "${SKIP_R:-}" ]] || ( Rscript $SIM/sim_fit_r.R $s 1 $NSIM > $SIM/logs/r_s$s.log 2>&1 ) &
done
wait
echo "fits done"
